class Daemon {
public:
    struct Version;
    enum DaemonState : int {
        STATE_UNKNOWN = 0x0,
        STATE_STOPPED = 0x1,
        STATE_STOPPING = 0x2,
        STATE_STARTING = 0x3,
        STATE_RUNNING = 0x4,
        STATE_INVALID = 0x5,
        STATE_FLUSHING = 0x6,
        STATE_COOLDOWNING = 0x7,
        STATE_COOLDOWNED = 0x8,
        STATE_RELOADING = 0x9,
        STATE_MAX = 0xA,
    };
    struct Version {
    public:
        union {
            unsigned long long version;
            unsigned short unit[4];
        };
    };
    virtual ~Daemon();  // slot 0
    virtual wchar_t const * ServiceName() = 0;  // slot 1
    virtual wchar_t const * ShortName() = 0;  // slot 2
    virtual wchar_t const * Name() = 0;  // slot 3
    virtual wchar_t const * Descriptions() = 0;  // slot 4
    virtual long GetTimerInterval() = 0;  // slot 5
    virtual long GetTimerMaxTime() = 0;  // slot 6
    virtual void PrintDependency() = 0;  // slot 7
    virtual bool initLog() = 0;  // slot 8
    virtual bool setArgument(int, wchar_t const * *) = 0;  // slot 9
    virtual bool initialize() = 0;  // slot 10
    virtual bool initNetwork() = 0;  // slot 11
    virtual bool onStart() = 0;  // slot 12
    virtual void shutdown() = 0;  // slot 13
    virtual bool reload(wchar_t * *, int) = 0;  // slot 14
    virtual bool cooldown();  // slot 15
    virtual void FlushExtraLog();  // slot 16
    ZSTD_CDict_s * _zstdCDic;
    unsigned char * _cDicBuffer;
    unsigned long long _cDicBufferSize;
    Console * console;
    PipeConsole * pipeConsole;
    ThreadManager * threadManager;
    Daemon::DaemonState State;
    SystemEvent EndEvent;
    long StartSystemTick;
    long long StartSystemTick64;
    long CurrentTick;
    long long StartTime;
    Daemon::Version Ver;
    wchar_t VerStr[32];
    wchar_t hostname[256];
    unsigned long publicAddress;
    wchar_t publicAddrString[20];
    unsigned long internalAddress;
    wchar_t internalAddrString[20];
    wchar_t confDir[520];
    _cidraddress internalCIDR;
    _cidraddress publicCIDR;
    bool setInternalCIDR;
    bool setPublicCIDR;
    TimerQueue * GlobalTimerQueue;
    DelayedRelease * GlobalDelayedRelease;
    bool allowClientIPAddressInLogs;
    bool allowClientSessionLifeCycleInLogs;
};
