class InstantPaymentJob {
public:
    enum INSTANT_PAYMENT_JOB_TYPE : int {
        INSTANT_PAYMENT_JOB_TYPE_NONE = 0x0,
        INSTANT_PAYMENT_JOB_TYPE_RANDOM_STORE_DRAW = 0x1,
        INSTANT_PAYMENT_JOB_TYPE_RANDOM_STORE_EXPAND = 0x2,
        INSTANT_PAYMENT_JOB_TYPE_TRANSFORM_ITEM = 0x3,
        INSTANT_PAYMENT_JOB_TYPE_BUY_COLLECTION_ITEM = 0x4,
        INSTANT_PAYMENT_JOB_TYPE_DRAW_SLATE_NEW_STONE = 0x5,
        INSTANT_PAYMENT_JOB_TYPE_COUNT = 0x6,
    };
    virtual ~InstantPaymentJob();  // slot 0
    virtual InstantPaymentJob::INSTANT_PAYMENT_JOB_TYPE GetType() = 0;  // slot 1
    virtual bool init(int, void *);  // slot 2
    virtual bool finishInstantPaymentReq(void *);  // slot 3
    virtual bool finishInstantPaymentOk(void *);  // slot 4
    virtual bool finishInstantPaymentFail(short);  // slot 5
    virtual bool finishAbort(void *);  // slot 6
    virtual bool procBeforePurchase(int, void *);  // slot 7
    virtual bool apply(int, void *);  // slot 8
    virtual bool procAfterPurchase(int, void *);  // slot 9
    virtual bool tryAbortImpl(short);  // slot 10
    virtual bool tryInstantPaymentFailImpl() = 0;  // slot 11
    virtual bool tryInstantPaymentOkImpl(void *) = 0;  // slot 12
    virtual int DataId();  // slot 13
    virtual int DataId(short) = 0;  // slot 14
    virtual void setExtraParam(void *) = 0;  // slot 15
    virtual void postFailProc() = 0;  // slot 16
    virtual void sendFailPacket(short) = 0;  // slot 17
    InstantPaymentTran * _tran;
    InstantPaymentGoodsInfoParam _goodsInfo;
    long long _resultServiceId;
    long long _resultPurchaseId;
    unsigned int _resultServiceTypes[10];
    short _resultServiceTypeCount;
    short _instantPaymentFailReason;
};
